/* Full-image preview shared by desktop and touch devices. */
.showcase-zoom {
  position: fixed;
  inset: 0;
  z-index: 240;
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  background: #0a0a0a;
  transition: opacity 0.25s ease, visibility 0s linear 0.25s;
}

.showcase-zoom.is-open {
  visibility: visible;
  opacity: 1;
  pointer-events: auto;
}

.showcase-zoom-track {
  width: 100%;
  height: 100%;
  display: flex;
  overflow-x: auto;
  overflow-y: hidden;
  scroll-snap-type: x mandatory;
  overscroll-behavior: contain;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}

.showcase-zoom-track::-webkit-scrollbar {
  display: none;
}

.showcase-zoom-slide {
  flex: 0 0 100%;
  min-width: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: max(64px, calc(16px + env(safe-area-inset-top))) clamp(16px, 3vw, 48px)
    max(84px, calc(72px + env(safe-area-inset-bottom)));
  scroll-snap-align: center;
}

.showcase-zoom-frame {
  min-width: 0;
  min-height: 0;
  width: 100%;
  max-height: 100%;
  flex: 0 1 auto;
  border-radius: 0;
}

.showcase-zoom-frame img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
  border-radius: 0;
  opacity: 0;
  transition: opacity 0.25s ease;
}

.showcase-zoom-frame img.is-loaded {
  opacity: 1;
}

.showcase-zoom-tags {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
}

.showcase-zoom-tags span {
  padding: 7px 12px;
  border-radius: 999px;
  background: rgba(250, 250, 250, 0.96);
  color: #111;
  font-size: clamp(11px, 2.9vw, 13px);
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.showcase-zoom button {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.5);
  border-radius: 6px;
  background: #161616;
  color: #fafafa;
  font-size: 24px;
  line-height: 1;
  cursor: pointer;
  touch-action: manipulation;
}

.showcase-zoom button:hover:not(:disabled) {
  background: #333;
}

.showcase-zoom button:disabled {
  opacity: 0.35;
  cursor: default;
}

.showcase-zoom .showcase-zoom-close {
  position: absolute;
  top: max(12px, env(safe-area-inset-top));
  right: max(16px, env(safe-area-inset-right));
  z-index: 2;
  font-size: 32px;
}

.showcase-zoom-controls {
  position: absolute;
  left: 50%;
  bottom: max(16px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 20px;
}

.showcase-zoom-count {
  min-width: 48px;
  color: #fafafa;
  text-align: center;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}

