/* ========================================= */
/* MASONRY GALLERY (For Esterni, Interni, Paesaggi) */
/* ========================================= */
.gallery-section {
  padding: 8vw 6.25vw;
  width: 100%;
  max-width: none;
  margin: 0 auto;
  position: relative;
  z-index: 10;
}

.masonry-gallery {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: clamp(150px, 18vw, 350px); /* responsive height */
  grid-auto-flow: dense;
  gap: 1.5vw;
  padding-bottom: 4vw;
}

.masonry-item {
  display: block;
  position: relative;
  overflow: hidden;
  border-radius: var(--media-card-radius);
  clip-path: inset(0 round var(--media-card-radius));
  cursor: pointer;
  grid-column: span 1;
  grid-row: span 1;
}

.masonry-item img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: inherit;
  transition: transform 0.5s ease;
}

.masonry-item::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 35%, rgba(0, 0, 0, 0.78) 100%);
  opacity: 0;
  pointer-events: none;
  transition: opacity 280ms ease;
}

.masonry-caption {
  position: absolute;
  z-index: 1;
  right: 0;
  bottom: 0;
  left: 0;
  padding: clamp(14px, 1.25vw, 20px);
  color: #fff;
  font-family: "Helvetica Neue", "Segoe UI", Helvetica, Arial, sans-serif;
  font-size: clamp(14px, 1.06vw, 17px);
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: 0.012em;
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.45);
  opacity: 0;
  transform: translateY(6px);
  pointer-events: none;
  transition: opacity 280ms ease, transform 280ms ease;
}

.masonry-item:is(:hover, :focus-visible)::after,
.masonry-item:is(:hover, :focus-visible) .masonry-caption {
  opacity: 1;
}

.masonry-item:is(:hover, :focus-visible) .masonry-caption {
  transform: translateY(0);
}

@media (hover: none), (max-width: 1024px) {
  .masonry-item::after,
  .masonry-caption {
    opacity: 1;
  }

  .masonry-caption {
    transform: none;
  }
}

/* Staggered, irregular horizontal rectangular crops for the grid view using CSS Grid spans */
/* Layout 1: Esterni */
.layout-1 .masonry-item:nth-child(1) { grid-column: span 2; grid-row: span 2; }
.layout-1 .masonry-item:nth-child(4) { grid-column: span 2; }
.layout-1 .masonry-item:nth-child(7) { grid-column: span 2; }
.layout-1 .masonry-item:nth-child(8) { grid-row: span 2; }

/* Layout 2: Interni */
.layout-2 .masonry-item:nth-child(2) { grid-column: span 2; }
.layout-2 .masonry-item:nth-child(3) { grid-row: span 2; }
.layout-2 .masonry-item:nth-child(5) { grid-column: span 2; grid-row: span 2; }
.layout-2 .masonry-item:nth-child(9) { grid-column: span 2; }

/* Layout 3: Paesaggi */
.layout-3 .masonry-item:nth-child(1) { grid-column: span 3; }
.layout-3 .masonry-item:nth-child(3) { grid-column: span 2; }
.layout-3 .masonry-item:nth-child(6) { grid-row: span 2; }
.layout-3 .masonry-item:nth-child(8) { grid-column: span 2; grid-row: span 2; }

@media (min-width: 1025px) {
  /* A compact contact sheet stays useful as the galleries grow. */
  .gallery-section .masonry-gallery {
    max-width: 1120px;
    margin-inline: auto;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    grid-auto-rows: clamp(150px, 14vw, 195px);
    gap: clamp(12px, 1.15vw, 18px);
    padding-bottom: clamp(32px, 3vw, 48px);
  }

  .gallery-section .masonry-gallery .masonry-item {
    grid-column: auto;
    grid-row: auto;
  }

  .gallery-section .layout-1,
  .gallery-section .masonry-gallery:has(> .masonry-item:nth-child(10)) {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .gallery-section .masonry-gallery:has(> .masonry-item:nth-child(17)) {
    grid-template-columns: repeat(5, minmax(0, 1fr));
    grid-auto-rows: clamp(130px, 11vw, 170px);
  }

  .gallery-section .layout-3:has(> .masonry-item:nth-child(2):last-child) {
    grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
    grid-auto-rows: clamp(220px, 23vw, 300px);
  }

  .gallery-section .layout-3:has(> .masonry-item:nth-child(2):last-child) .masonry-item:nth-child(2) img {
    object-position: 70% center;
  }
}

.masonry-item:hover img {
  transform: scale(1.05);
}

@media (min-width: 1025px) and (hover: hover) and (pointer: fine) {
  .masonry-gallery.is-bento {
    transition: grid-template-columns 420ms cubic-bezier(0.22, 1, 0.36, 1),
      grid-template-rows 420ms cubic-bezier(0.22, 1, 0.36, 1);
  }

  .masonry-gallery.is-bento .masonry-item {
    min-width: 0;
    min-height: 0;
    clip-path: none;
  }

  .masonry-gallery.is-bento .masonry-item img,
  .masonry-gallery.is-bento .masonry-item:hover img {
    transform: none;
  }

  .masonry-gallery.is-bento .masonry-item:focus-visible {
    z-index: 2;
    outline: 2px solid #fff;
    outline-offset: -5px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .masonry-gallery.is-bento { transition: none; }
  .masonry-item::after,
  .masonry-caption { transition: none; }
}

