/* PHOTOSWIPE CUSTOM STYLES (Lightbox) */
/* ========================================= */
.pswp__bg {
  background: rgba(0, 0, 0, 0.8) !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
}

.pswp__button {
