}

.section-wrapper {
  scroll-snap-align: none;
}

.home-page #intro {
  min-height: 0;
  padding: clamp(144px, 19svh, 220px) var(--home-gutter)
    clamp(108px, 15svh, 174px);
}

.home-page #intro h1 {
  max-width: 20ch;
  margin-inline: auto;
  text-wrap: balance;
}

.home-page .scroll-showcase {
  --showcase-stage-top: clamp(70px, 11svh, 120px);
  --showcase-stage-height: min(76svh, 760px);
  --showcase-step-height: clamp(330px, 52svh, 530px);
  min-height: 0;
  padding: 0 var(--home-gutter);
  overflow: visible;
}

.home-page #main-content-wrapper {
