}

.home-page .scroll-showcase .scroll-showcase-stack {
  height: var(--showcase-stage-height);
  min-height: var(--showcase-stage-height);
}

.home-page .scroll-showcase .scroll-showcase-stage {
  position: relative;
  top: auto;
  height: var(--showcase-stage-height);
  display: block;
  padding: 0;
  overflow: hidden;
  clip-path: none;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 8px;
  background: #111;
  box-shadow: 0 18px 54px rgba(0, 0, 0, 0.22);
}

.home-page .scroll-showcase-track {
  display: flex;
  width: 100%;
  height: 100%;
  gap: 0;
  overflow-x: auto;
  overflow-y: hidden;
  scroll-snap-type: x mandatory;
  overscroll-behavior-inline: contain;
}

.home-page .scroll-showcase .scroll-showcase-card {
  position: relative;
  inset: auto;
  flex: 0 0 100%;
  min-width: 100%;
  width: 100%;
  height: 100%;
  aspect-ratio: auto;
  border: 0;
  border-radius: 0;
  clip-path: none;
  transform: none;
  opacity: 1;
  will-change: auto;
  box-shadow: none;
  scroll-snap-align: start;
}

.home-page .scroll-showcase-card[role="button"] {
