}

.home-page .scroll-showcase-card img {
  transform: none;
  will-change: auto;
  object-position: center;
}

.home-page .scroll-showcase .showcase-tags {
  left: clamp(22px, 2.4vw, 38px);
  bottom: clamp(24px, 3vw, 44px);
