  z-index: 7;
  right: clamp(20px, 2.5vw, 38px);
  bottom: clamp(20px, 2.5vw, 38px);
  color: #fff;
}

.home-page .scroll-showcase.is-ready .showcase-controls {
  display: flex;
}

.home-page .showcase-count {
  min-width: 68px;
  margin-right: 8px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.14em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 1px 8px #000;
}

.home-page .showcase-count-separator {
  opacity: 0.55;
}

.home-page .showcase-button {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.65);
  border-radius: 50%;
  background: rgba(14, 14, 14, 0.46);
  color: #fff;
  font: inherit;
  font-size: 23px;
  line-height: 1;
