.home-page .showcase-button:disabled {
  opacity: 0.38;
  cursor: default;
}

@media (min-width: 768px) and (prefers-reduced-motion: no-preference) {
  .home-page .scroll-showcase.is-enhanced .scroll-showcase-stack {
    height: calc(var(--showcase-stage-height) + (var(--showcase-card-count, 4) - 1) * var(--showcase-step-height));
  }

  .home-page .scroll-showcase.is-enhanced .scroll-showcase-stage {
    position: sticky;
    top: var(--showcase-stage-top);
  }

  .home-page .scroll-showcase.is-enhanced .scroll-showcase-track {
    position: relative;
    overflow: hidden;
    scroll-snap-type: none;
  }

  .home-page .scroll-showcase.is-enhanced .scroll-showcase-card {
    position: absolute;
    inset: 0;
    min-width: 0;
    transform: translate3d(0, 100%, 0);
    scroll-snap-align: none;
  }

  .home-page .scroll-showcase.is-enhanced .scroll-showcase-card:first-child {
    transform: translate3d(0, 0, 0);
  }

  .home-page .scroll-showcase.is-enhanced.is-in-view .scroll-showcase-card {
    will-change: transform;
  }
}

